// (원래 app.js에 있던 코드를 그대로 가져왔고, 서버 공고·이메일 로그인에 맞게 바뀐 곳에만 설명을 달았다.)
Object.assign(state,{saved:read('saved',[]),products:read('products',[]),posts:read('posts',null),compare:[],board:'통합',ageFilter:'전체 연령',jobFilter:'전체 분야',boardSearch:''});
const initialPosts=[
{id:1,board:'청약·집 구하기',title:'처음 청약 준비하는데, 어디서부터 보면 좋을까요?',body:'청약통장은 있는데 공고문을 읽으려니 처음 보는 용어가 많네요. 다들 어떤 순서로 준비하셨는지 궁금해요. 경험 공유 부탁드립니다!\n\n※ 서비스 이용 흐름을 보여주기 위한 예시 게시글입니다.',age:'20대',job:'일반',author:'익명 새싹',likes:18,comments:[{author:'익명 이웃',body:'지역과 공급 유형부터 골라보고, 그 공고의 신청 조건을 읽어보면 덜 복잡하더라고요.'}],time:'오늘'},
{id:2,board:'금융생활',title:'전세 준비할 때 보증금 외에 어떤 비용을 챙기나요?',body:'이사비, 중개보수 외에 놓치기 쉬운 항목이 있을까요? 자금 계획 체크리스트를 만들어보려고 합니다.\n\n※ 예시 게시글이며 금융 조언이 아닙니다.',age:'30대',job:'은행',author:'익명 나무',likes:12,comments:[],time:'오늘'},
{id:3,board:'취업·커리어',title:'금융권 데이터 직무 준비하는 분들, 함께 이야기해요',body:'고객 세분화나 행동 분석 프로젝트를 준비하는 분들과 공부 방법을 나누고 싶어요. 데이터 직무 관심 있으신가요?\n\n※ 예시 게시글입니다.',age:'20대',job:'데이터',author:'익명 구름',likes:25,comments:[],time:'어제'},
{id:4,board:'자유',title:'출퇴근 시간과 집 크기, 여러분은 무엇이 더 중요한가요?',body:'집을 고를 때 가장 고민되는 게 거리와 공간이에요. 여러분의 우선순위가 궁금합니다.\n\n※ 예시 게시글입니다.',age:'40대 이상',job:'보험',author:'익명 온기',likes:9,comments:[],time:'어제'}];
if(!state.posts)state.posts=initialPosts;
const boards=['통합','인기 글','청약·집 구하기','금융생활','취업·커리어','자유'];
function community(){let posts=state.posts.filter(p=>(['통합','인기 글'].includes(state.board)||p.board===state.board)&&(state.ageFilter==='전체 연령'||p.age===state.ageFilter)&&(state.jobFilter==='전체 분야'||p.job===state.jobFilter)&&`${p.title} ${p.body}`.includes(state.boardSearch));if(state.board==='인기 글')posts.sort((a,b)=>b.likes-a.likes);return `<div class="wrap page reveal"><div class="page-title"><div class="eyebrow">OUR LITTLE NEIGHBORHOOD</div><h1>비슷한 고민, 함께 나눠요.</h1><p>집과 금융생활, 취업 이야기까지. 통합 게시판에서 모든 주제의 글을 만나보세요.</p></div><div class="board-layout"><aside class="panel board-sidebar"><h3>함께 보는 공간</h3>${boards.map(b=>`<button class="board-link ${state.board===b?'active':''}" data-action="board" data-value="${b}">${b}</button>`).join('')}<h3>게시판 이용</h3><button class="board-link" data-action="community-rules">이용 안내 ↗</button></aside><section><div class="section-head"><h2>${state.board} <small>${posts.length}개 글</small></h2><button class="btn small" data-action="write">＋ 글쓰기</button></div><form class="search-row" id="board-search"><input aria-label="게시글 검색" placeholder="함께 나누고 싶은 이야기를 검색하세요" value="${esc(state.boardSearch)}"><button class="btn secondary" type="submit">검색</button></form><div class="board-filter"><select aria-label="연령대 필터" data-filter="ageFilter">${['전체 연령','20대','30대','40대 이상'].map(t=>`<option ${t===state.ageFilter?'selected':''}>${t}</option>`).join('')}</select><select aria-label="분야 필터" data-filter="jobFilter">${['전체 분야','일반','은행','보험','카드','데이터'].map(t=>`<option ${t===state.jobFilter?'selected':''}>${t}</option>`).join('')}</select><button class="text-link" data-action="clear-board">초기화</button></div><div class="post-list">${posts.length?posts.map(p=>`<a href="#post/${p.id}" class="post-row"><div style="min-width:0"><div class="tags"><span class="badge gray">${esc(p.board)}</span><span class="tag">${esc(p.age)}</span><span class="tag">${esc(p.job)}</span><span class="tag">예시</span></div><h3>${esc(p.title)}</h3><p>${esc(p.body.split('\n')[0])}</p><div class="post-meta"><span>${esc(p.author)}</span><span>${p.time}</span><span>댓글 ${p.comments.length}</span></div></div><div class="post-score">♡<br>${p.likes}</div></a>`).join(''):'<div class="empty" style="border:0"><h3>이 조건의 글이 아직 없어요</h3><p>필터를 바꾸거나 첫 이야기를 남겨보세요.</p></div>'}</div><p class="demo-note">연령·분야는 예시 프로필 태그입니다. 별도 인증 없이 익명 이용 흐름을 시연합니다.<br>이 목업에서 작성한 글은 다른 방문자에게 공유되지 않고 현재 브라우저에만 저장됩니다.</p></section></div></div>`}
function post(id){const p=state.posts.find(p=>p.id===Number(id));if(!p)return emptyPage('게시글을 찾을 수 없어요','목록에서 다시 선택해 주세요.','community','목록으로');return `<div class="wrap page reveal"><div class="breadcrumbs"><a href="#community">커뮤니티</a> / ${esc(p.board)}</div><article class="panel post-detail"><div class="tags"><span class="badge">${esc(p.board)}</span><span class="tag">${esc(p.age)} · ${esc(p.job)}</span><span class="tag">목업 게시글</span></div><h2>${esc(p.title)}</h2><div class="post-meta"><span>${esc(p.author)}</span><span>${p.time}</span><span>댓글 ${p.comments.length}</span></div><p class="post-content">${esc(p.body)}</p><div style="display:flex;gap:10px"><button class="btn soft small" data-action="like" data-id="${p.id}">♡ 공감 ${p.likes}</button><button class="btn secondary small" data-action="report-post" data-id="${p.id}">신고</button><a href="#community" class="btn secondary small">목록으로</a></div><div class="comments"><h3>댓글 ${p.comments.length}</h3>${p.comments.map(c=>`<div class="comment"><strong>${esc(c.author)}</strong><p>${esc(c.body)}</p></div>`).join('')}<form class="reply-form" id="comment-form" data-id="${p.id}"><input placeholder="이야기를 남겨 주세요" aria-label="댓글" maxlength="1000" required><button class="btn" type="submit">등록</button></form></div></article></div>`}
function preferencesPage(){const p=read('preferences',{교통:3,생활편의:3,교육환경:3,destination:'강남역',time:'60분'});return `<div class="wrap page reveal"><div class="page-title"><div class="eyebrow">MY PRIORITIES</div><h1>나는 어떤 집에서 살고 싶을까요?</h1><p>중요하게 생각하는 기준을 정리해 두세요. 실제 입지 점수를 산정하는 기능은 아닙니다.</p></div><form id="preferences-form" class="panel"><div class="grid3">${['교통','생활편의','교육환경'].map(t=>`<div class="field"><label for="pref-${t}">${t} 중요도</label><input id="pref-${t}" type="range" min="1" max="5" value="${p[t]}"><small>덜 중요 1 · 보통 3 · 매우 중요 5</small></div>`).join('')}</div><div class="form-row"><div class="field"><label for="pref-destination">자주 가는 장소</label><input id="pref-destination" value="${esc(p.destination)}" placeholder="정확한 주소 대신 역 이름도 괜찮아요"></div><div class="field"><label for="pref-time">희망 이동시간</label><select id="pref-time">${['30분','45분','60분','90분'].map(t=>`<option ${t===p.time?'selected':''}>${t}</option>`).join('')}</select></div></div><button class="btn" type="submit">내 집 기준 저장 →</button><div class="callout">저장한 기준은 내 취향을 정리하는 용도입니다. 추천 순위·실제 교통 조회에 반영하는 기능은 후속 연동 항목입니다.</div></form></div>`}
function writePost(){requireLogin(()=>modal(`<div class="eyebrow">SHARE YOUR STORY</div><h2>우리 이야기 남기기</h2><p>목업 체험용 글입니다. 현재 브라우저에서만 보여요.</p><form id="post-form"><div class="form-row"><div class="field"><label for="post-board">주제</label><select id="post-board">${boards.slice(2).map(t=>`<option>${t}</option>`).join('')}</select></div><div class="field"><label for="post-age">연령 태그</label><select id="post-age">${['20대','30대','40대 이상'].map(t=>`<option>${t}</option>`).join('')}</select></div></div><div class="field"><label for="post-job">분야 태그</label><select id="post-job">${['일반','은행','보험','카드','데이터'].map(t=>`<option>${t}</option>`).join('')}</select></div><div class="field"><label for="post-title">제목</label><input id="post-title" maxlength="80" required placeholder="함께 나누고 싶은 고민은?"></div><div class="field"><label for="post-body">내용</label><textarea id="post-body" rows="5" maxlength="5000" required placeholder="실명·연락처 등 개인정보는 적지 마세요."></textarea></div><button class="btn full" type="submit">체험 글 등록 →</button></form>`))}
const financials={대출:[['새봄은행','전월세 대출 안내','공개 조건 확인','보증 기관·주택 종류·소득 조건을 확인하는 정보 화면입니다.'],['온빛은행','주택담보대출 안내','상환 방식 살펴보기','고정·변동금리와 상환기간 등 비교 항목을 정리합니다.'],['다온은행','신용대출 안내','심사 항목 알아보기','공개된 기본 정보를 읽고 공식 안내로 이동하는 흐름입니다.']],예적금:[['새봄은행','차곡 정기예금','연 3.0%','12개월 · 기본금리 예시 · 세전'],['온빛은행','매일 조금씩 적금','연 3.5%','12개월 · 기본금리 예시 · 세전'],['다온은행','자유 저축 예금','연 2.8%','6개월 · 기본금리 예시 · 세전']],카드:[['새봄카드','생활의 기본','대중교통 · 통신','전월 실적과 월 할인 한도를 함께 확인하는 카드 예시'],['온빛카드','우리집 생활','마트 · 생활비','생활 분야별 혜택을 비교하는 카드 예시'],['다온카드','가볍게 출발','온라인 · 구독','연회비와 혜택 적용 조건을 확인하는 카드 예시']]};
function productCards(tab,filter='전체'){const list=financials[tab]||[];return list.filter(p=>filter==='전체'||p.join(' ').includes(filter)).map((p,i)=>`<article class="product-card"><div class="product-top"><div class="product-logo">${p[0][0]}</div><div><h3>${p[0]}</h3><small>가상 기관 · 예시 상품</small></div></div><span class="badge gray">${p[1]}</span><div class="product-number" style="font-size:${tab==='대출'?22:27}px">${p[2]}</div><p>${p[3]}</p><button class="btn secondary" data-action="product" data-tab="${tab}" data-id="${i}">상세 정보 보기 ↗</button></article>`).join('')}
function insurance(){return `<div class="section-head"><div><h2>보험 용어부터 쉽게 알아봐요</h2><p>개인별 보험 가입·보장 분석 없이 기본 개념을 안내합니다.</p></div></div><div class="grid3">${[['shield','보장 범위','무엇을 보장하고, 어떤 경우에 제외되는지 확인하는 항목입니다.'],['money','보험료와 납입기간','매달 납입 금액, 납입기간과 보장기간은 서로 다를 수 있습니다.'],['check','가입 전 체크리스트','갱신 여부, 면책·감액기간, 기존 보장 중복을 함께 확인합니다.']].map(([i,t,d])=>`<article class="panel insurance-card">${icon(i)}<h3>${t}</h3><p>${d}</p><button class="text-link" data-action="insurance" data-value="${t}" style="margin-top:20px">자세히 알아보기 ↗</button></article>`).join('')}</div>`}
function savedPage(){if(!state.user?.member)return `<div class="wrap page"><div class="empty">${icon('check')}<h3>로그인하면 관심 공고를 모아 볼 수 있어요</h3><p>공고 카드의 하트를 눌러 저장하고, 최대 3개까지 비교해 보세요.</p><button class="btn" data-action="signup">로그인</button></div></div>`;
  const list=state.saved.map(houseById).filter(Boolean);
  state.saved.filter(id=>!houseById(id)).forEach(id=>ensureHouse(id));   // 새로고침 뒤에는 서버에서 다시 받아 온다 (받으면 ensureHouse가 화면을 다시 그린다)
  return `<div class="wrap page"><div class="page-title"><div class="eyebrow">SAVED PLACES</div><h1>관심 공고</h1><p>마음에 드는 집을 모아두고 최대 3개까지 비교해 보세요.</p></div>${state.saved.length?`<div class="grid3">${list.map(h=>houseCard(h,true)).join('')}</div>`:'<div class="empty"><h3>저장한 공고가 없어요</h3><a href="#homes" class="btn">공고 둘러보기</a></div>'}${state.compare.length?`<div class="sticky-compare"><span>비교 후보 ${state.compare.length} / 3</span><button class="btn" data-action="compare-open">비교하기 →</button></div>`:''}</div>`}
function compareModal(){const hs=state.compare.map(houseById).filter(Boolean);if(hs.length<2){toast('공고를 2개 이상 골라 주세요.');return}modal(`<div class="eyebrow">COMPARE YOUR OPTIONS</div><h2>관심 공고 비교</h2><p>서버에서 받은 공고 정보를 같은 기준으로 살펴보세요. 없는 값은 공고문 확인으로 표시합니다.</p><div class="table-wrap"><table><thead><tr><th>비교 항목</th>${hs.map(h=>`<th>${esc(h.name)}</th>`).join('')}</tr></thead><tbody>${[['위치',h=>esc(h.loc)],['공급 유형',h=>esc(h.type)],['면적',h=>esc(h.area)],['분양가·보증금',h=>moneyOr(h.price)],['접수 일정',h=>h.date],['접수 상태',h=>h.status],['신청 자격',()=>'원문 확인 필요']].map(([t,fn])=>`<tr><td>${t}</td>${hs.map(h=>`<td>${fn(h)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`,true)}

// community-v2/v3.js가 불러올 때 guide·profile이 있어야 한다. 진짜 화면은 live.js가 같은 이름으로 다시 정의한다
function guide(){}
function profile(){return ''}

// 로그인(이메일·닉네임)한 사람만 쓸 수 있는 기능: 아니면 로그인 창을 열고, 로그인하면 하려던 일을 이어서 한다 (live.js가 로그인 뒤에 afterLogin을 부른다)
let afterLogin=null;
function requireLogin(callback){if(state.user?.member){callback();return}afterLogin=callback;login()}

// ───── 이벤트: 되살린 화면의 버튼 ─────
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const act=b.dataset.action,id=Number(b.dataset.id),v=b.dataset.value;switch(act){
  case'close':afterLogin=null;break;   // 로그인 창을 그냥 닫으면 하려던 일은 취소
  case'save-house':requireLogin(()=>{state.saved=state.saved.includes(id)?state.saved.filter(n=>n!==id):[...state.saved,id];save('saved',state.saved);render();toast(state.saved.includes(id)?'관심 공고에 저장했어요.':'저장을 취소했어요.')});break;
  case'compare-open':compareModal();break;
  case'compare-clear':state.compare=[];render();break;
  case'card-filter':document.querySelectorAll('[data-action="card-filter"]').forEach(x=>x.classList.toggle('active',x.dataset.value===v));$('#product-grid').innerHTML=productCards('카드',v);break;
  case'product':{const p=financials[b.dataset.tab][id];modal(`<span class="badge gray">가상 상품 · 화면 예시</span><h2 style="margin-top:15px">${p[1]}</h2><p>${p[0]} · ${p[3]}</p><div class="kv"><span>요약 정보</span><strong>${p[2]}</strong></div><div class="kv"><span>비교할 항목</span><strong>비용·기간·적용 조건</strong></div><div class="kv"><span>정보 상태</span><strong>공식 상품 연결 전</strong></div><p style="margin-top:20px">실제 금리·혜택은 제공하지 않습니다. 상세 조건과 출처를 확인한 뒤 관심 정보로 저장하는 흐름입니다.</p><button class="btn full" data-action="save-product" data-value="${p[1]}">관심 정보 저장</button>`);break}
  case'save-product':requireLogin(()=>{if(!state.products.includes(v))state.products.push(v);save('products',state.products);closeModal();toast('관심 금융 정보에 저장했어요.')});break;
  case'insurance':modal(`<div class="eyebrow">INSURANCE BASICS</div><h2>${esc(v)}</h2><p>보험을 읽을 때 확인할 기본 개념을 정리합니다.</p><ul class="plain-list"><li>상품설명서의 보장 범위와 제외 항목</li><li>갱신 여부와 보험료 변동 가능성</li><li>납입기간·보장기간·해지 조건</li><li>기존 보험과 보장 중복 여부</li></ul><p style="margin-top:20px;margin-bottom:0">개별 보험 가입 권유나 건강 상태 분석은 제공하지 않습니다.</p>`);break;
  case'board':state.board=v;render();break;
  case'clear-board':state.ageFilter='전체 연령';state.jobFilter='전체 분야';state.boardSearch='';render();break;
  case'write':writePost();break;
  case'community-rules':modal('<h2>함께 쓰는 공간의 약속</h2><p>익명으로 편하게 이야기하되 서로 존중해 주세요.</p><ul class="plain-list"><li>개인정보·타인의 실명·연락처를 공개하지 않아요.</li><li>대출 모집·상품 판매·투자 권유 글은 올리지 않아요.</li><li>비방·혐오·허위 정보는 신고 대상입니다.</li><li>연령·분야 태그는 자율 선택이며 인증을 의미하지 않습니다.</li></ul><p class="demo-note">신고·차단은 화면 예시이며 운영 서버와 연결되어 있지 않습니다.</p>');break;
  case'like':{const p=state.posts.find(p=>p.id===id);requireLogin(()=>{const liked=read('liked',[]);if(liked.includes(id)){toast('이미 공감한 글이에요.');return}p.likes++;save('liked',[...liked,id]);save('posts',state.posts);render()});break}
  case'report-post':modal(`<h2>게시글 신고</h2><p>신고 화면을 체험합니다. 운영자에게 실제 전달되지 않습니다.</p><select id="report-reason" aria-label="신고 사유"><option>금융 광고·사기 의심</option><option>개인정보 노출</option><option>비방·혐오 표현</option><option>기타</option></select><button class="btn full" style="margin-top:20px" data-action="send-report">신고 접수 체험</button>`);break;
  case'send-report':closeModal();toast('신고 접수 화면을 체험했어요. 실제 전송은 없습니다.');break;
}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.action==='compare'){const id=Number(el.dataset.id);if(el.checked){if(state.compare.length>=3){el.checked=false;toast('비교는 최대 3개까지 가능해요.');return}state.compare.push(id)}else state.compare=state.compare.filter(n=>n!==id);render()}});
document.addEventListener('submit',e=>{const form=e.target;switch(form.id){
  case'board-search':e.preventDefault();state.boardSearch=form.querySelector('input').value.trim();render();break;
  case'post-form':{e.preventDefault();const p={id:Date.now(),board:$('#post-board').value,age:$('#post-age').value,job:$('#post-job').value,title:$('#post-title').value.trim(),body:$('#post-body').value.trim(),author:'익명 '+state.user.name,likes:0,comments:[],time:'방금'};if(!p.title||!p.body){toast('제목과 내용을 입력해 주세요.');return}state.posts.unshift(p);save('posts',state.posts);go('post/'+p.id);toast('글을 이 브라우저에 저장했어요.');break}
  case'comment-form':{e.preventDefault();const body=form.querySelector('input').value.trim(),id=Number(form.dataset.id);if(!body)return;requireLogin(()=>{state.posts.find(p=>p.id===id).comments.push({author:'익명 '+state.user.name,body});save('posts',state.posts);render();toast('댓글을 이 브라우저에 저장했어요.')});break}
  case'preferences-form':{e.preventDefault();const p={};for(const t of ['교통','생활편의','교육환경'])p[t]=Number($('#pref-'+t).value);p.destination=$('#pref-destination').value.trim();p.time=$('#pref-time').value;save('preferences',p);toast('내 집 기준을 이 브라우저에 저장했어요.');break}
}});
